"""One preferences component shared by every public page."""


def preferences_notice(reader=False):
    reader_controls = '''<section class="preference-group"><h3>Text size</h3><div class="text-size-control"><button class="consent-button" id="smaller" type="button" aria-label="Make text smaller">A−</button><output id="reading-size-label" aria-live="polite">Default</output><button class="consent-button" id="larger" type="button" aria-label="Make text larger">A+</button></div></section>''' if reader else ''
    return '''<dialog class="consent-notice" id="site-preferences" aria-labelledby="preferences-title" aria-describedby="preferences-intro"><button class="preferences-close" type="button" data-preferences-close aria-label="Close preferences">×</button><h2 id="preferences-title">Your preferences</h2><p id="preferences-intro">Optionally remember your reading place and settings on this device, and allow cookie-free Vercel visit statistics. Both are off until you choose. <a href="privacy.html">Privacy</a></p><div id="preferences-manage" hidden>''' + reader_controls + '''<section class="preference-group"><label class="preference-choice"><span>Remember reading settings</span><input id="preference-memory" type="checkbox"></label><p>Keep your place, text size and desktop contents preference on this device. These reading details are not sent to us.</p></section><section class="preference-group"><label class="preference-choice"><span>Visit statistics</span><input id="preference-analytics" type="checkbox"></label><p>Let Vercel count visits and page views. No reading position, search text or glossary clicks are sent.</p><p id="preferences-signal" hidden>Your browser’s privacy signal keeps statistics off.</p></section></div><p id="preferences-error" role="status" hidden></p><div class="consent-notice-actions"><button class="consent-button consent-button-primary" id="preferences-accept" type="button">Accept all</button><button class="consent-button" id="preferences-reject" type="button">Reject optional</button><button class="consent-button consent-button-primary" id="preferences-save" type="button" hidden>Save choices</button></div><button class="preferences-manage-link" type="button" id="preferences-manage-button">Manage preferences</button></dialog>'''
